const openRegister = (entry, extra) => `<p>The ${entry.number} number and mission requirement belong to the incorporated Deep-Space Century scheme.<sup class='canon-note' data-provenance='e'>[e]</sup> ${extra} Its official name, contractor, precise authorization and flight dates, dimensions, mass, propulsion fit, performance, production total, operating unit, and final disposition remain open.</p>`;

const requirementArticle = (entry, config) => ({
  title:`${entry.number} ${config.shortTitle}`,
  category:"Space vehicles",
  eyebrow:`Deep-Space Century requirement · ${entry.period}`,
  infoboxKicker:"Orbit-resident American vehicle requirement",
  infoboxTitle:entry.number,
  lead:config.lead,
  canon:`The ${entry.number} designation, its place in the O-100 through O-109 Deep-Space Century, the ${config.canonRole}, and its broad ${entry.period} planning horizon are incorporated extrapolation from an assistant-developed requirement scheme.<sup class='canon-note' data-provenance='e'>[e]</sup> ${config.canonOpen}`,
  sections:config.sections,
  related:requirementRelated(entry,config.complements || []),
  facts:[["Working country of origin",`United States${deepSpaceRequirementExtrapolation}`],["Working designation",`${entry.number}${deepSpaceRequirementExtrapolation}`],["Working program block",`Deep-Space Century${deepSpaceRequirementExtrapolation}`],["Working requirement",`${entry.label}${deepSpaceRequirementExtrapolation}`],["Working broad period",`${entry.period}${deepSpaceRequirementExtrapolation}`],["Working primary environment",`Orbit and deep space${deepSpaceRequirementExtrapolation}`],["Working atmospheric capability",`Not required${deepSpaceRequirementExtrapolation}`],["Working operating institution",`United States Aerospace Force · planned${deepSpaceRequirementExtrapolation}`],["Official name","Open"],["Detailed configuration","Open"]],
  sources:[...deepSpaceRequirementSources,...(config.sources || [])],
  categories:["United States","United States Aerospace Force","Space vehicles","Deep-Space Century"]
});

const r101=deepSpaceRequirementLinks[0],r102=deepSpaceRequirementLinks[1],r103=deepSpaceRequirementLinks[2],r104=deepSpaceRequirementLinks[3],r105=deepSpaceRequirementLinks[4],r106=deepSpaceRequirementLinks[5],r107=deepSpaceRequirementLinks[6],r108=deepSpaceRequirementLinks[7],r109=deepSpaceRequirementLinks[8];

Object.assign(window.deepArticles, {
  [r101.slug]: requirementArticle(r101,{
    shortTitle:"cislunar dispatch requirement",
    lead:"O-101 was the Deep-Space Century requirement for a fast orbit-resident craft carrying people, dispatches, and urgent cargo through cislunar space. It was intended for journeys that began and ended away from Earth's surface, removing the wings, landing gear, ascent machinery, and reentry structure imposed upon an orbital spaceplane.",
    canonRole:"fast cislunar personnel and dispatch role",
    canonOpen:"<!-- altwwii-writer-block:start id=wb-g-20260816-o1a5e writer=g kind=revision created=2026-08-16T10:10:00-06:00 -->The developed register suggests a compact courier and makes thrust important to its human and urgent-cargo mission; these are extrapolated role boundaries rather than a fixed design.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    complements:[{href:"o-10-cislunar-spaceplane.html",kicker:"Atmospheric predecessor",label:"O-10 Cislunar Spaceplane"},{href:"o-103-propellant-tanker-depot-tender.html",kicker:"Route infrastructure",label:"O-103 Tanker and Depot Tender"}],
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>O-101 reserved fast transport between orbital ports, lunar facilities, high Earth orbits, and other cislunar destinations. People and urgent cargo gave travel time greater weight than bulk efficiency. The craft was not required to launch from or land on Earth.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The requirement covered a reusable vehicle rather than a complete Earth-to-Moon journey. Earth departure and return remained the work of spaceplanes or other launch craft; lunar-surface movement required a lander or surface transport.</p>"},
      {id:"operating-problem",title:"Operating problem",html:"<p>The <a href='o-10-cislunar-spaceplane.html'>O-10 spaceplane</a> could cross cislunar distances and still return to a runway. Every such journey carried atmospheric structure through a route where it performed no useful work. O-101 separated the cislunar passenger leg from the Earth-to-orbit ferry leg.</p><p>Passengers would transfer at <a href='orbital-port-columbia.html'>Orbital Port Columbia</a>, <a href='kennedy-lunar-station.html'>Kennedy Station</a>, or another certified terminal. This imposed scheduled docking, baggage and cargo transfer, pressure checks, passenger accounting, and protected connections between vehicles.<sup class='canon-note' data-provenance='e'>[e]</sup> Exact routes and terminals remain open.</p>"},
      {id:"missions",title:"Mission categories",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Mission</th><th>Typical load</th><th>Planning priority</th></tr></thead><tbody><tr><td>Personnel dispatch</td><td>Relief crews, inspectors, technical teams, officials</td><td>Arrival at a required duty window</td></tr><tr><td>Medical movement</td><td>Patients, medical specialists, blood products, clinical equipment</td><td>Short elapsed time and stable cabin conditions</td></tr><tr><td>Technical courier</td><td>Replacement electronics, tools, samples, records</td><td>Fast delivery with positive custody</td></tr><tr><td>Command movement</td><td>Military or civil command parties and secure dispatches</td><td>Communications security and schedule control</td></tr><tr><td>Contingency support</td><td>Small repair parties, rescue augmentation, emergency stores</td><td>Rapid availability rather than maximum payload</td></tr></tbody></table></div><p>These categories describe functions compatible with the fixed dispatch requirement; they do not establish a published route table or an operational fleet.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"configuration",title:"Configuration",html:"<p>The developed record permits a compact courier form. A pressure cabin, command spaces, docking systems, maneuvering propulsion, consumables, emergency stores, and a small protected-cargo compartment would dominate the vehicle. The fixed American orientation vocabulary placed the command area forward and dorsal and the principal propulsion system aft.</p><p>The absence of wings and Earth reentry protection did not remove the need for micrometeoroid protection, radiation shelter, fire isolation, pressure-section closure, and accessible life-support machinery. Cabin size, crew, passenger number, artificial gravity, and cargo arrangement are not fixed.</p>"},
      {id:"propulsion",title:"Propulsion and trajectory",html:"<p>Thrust matters because passengers, dispatches, and high-value cargo cannot always exchange weeks of travel for propellant economy.<sup class='canon-note' data-provenance='e'>[e]</sup> Chemical or other comparatively high-thrust propulsion is compatible with the requirement; the final engine school is unselected.</p><p>A dispatch mission would be planned around departure opportunity, destination orbit, arrival geometry, reserve propellant, and a diversion or safe-haven case. Faster transit usually demanded more propulsive work and could reduce the payload or reserve carried on a given departure.<sup class='canon-note' data-provenance='e'>[e]</sup> The requirement does not fix one standard Earth–Moon flight time.</p>"},
      {id:"navigation",title:"Navigation and communications",html:"<p>Cislunar operation required navigation across changing Earth and lunar reference frames, continuous ephemeris updates, rendezvous guidance, traffic coordination, and communications able to survive temporary loss of a direct ground link. A passenger craft also required an independent distress beacon and a trajectory record available to rescue authorities.</p><p>Command dispatches and military passengers introduced protected communications and controlled document or data custody. No avionics suite, communications network, or security equipment is selected in the current record.</p>"},
      {id:"passengers",title:"Passenger and cargo accommodation",html:"<p>The cabin requirement extended beyond seats. Passengers needed restraint, food and water, sanitation, medical oxygen, thermal control, emergency pressure protection, and a sheltered position during solar or debris warnings. Short-duration accommodation could remain denser than a survey or expedition ship.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Urgent cargo required known mass properties, secure restraint, fire and contamination classification, and access without opening the complete pressure cabin. Medical and biological loads could require temperature control and separate power.</p>"},
      {id:"interfaces",title:"Docking and servicing interfaces",html:"<p>The craft required docking compatibility, traffic clearance, rescue beacons, life-support replenishment, electrical and data connections, and propellant access. The <a href='o-103-propellant-tanker-depot-tender.html'>O-103 requirement</a> treated fuel supply as an independent system rather than an incidental station service.</p><p>Turnaround would include pressure and leak checks, cabin cleaning, consumables loading, fault review, navigation-data loading, cargo restraint inspection, and verification of the receiving berth. The O-101 requirement does not establish whether a crew remained assigned to one hull or changed at each terminal.</p>"},
      {id:"network",title:"Place in the cislunar network",html:"<p>O-101 occupied the fast end of the Deep-Space Century transport system. <a href='o-102-heavy-cislunar-freight-tug.html'>O-102</a> carried loads that could accept slower movement, O-103 supplied propellant, and <a href='o-104-deep-space-rescue-recovery.html'>O-104</a> addressed casualties outside normal station range. Commercial passenger craft later competed with parts of the federal dispatch role.</p><p>The continued military value lay in protected movement, unusual destinations, readiness, and traffic that a scheduled carrier could not guarantee.</p>"},
      {id:"status",title:"Program status",html:openRegister(r101,"Its compact-courier form and high-thrust preference remain developed role guidance rather than a selected airframe.")}
    ],
    sources:[{href:"https://ntrs.nasa.gov/api/citations/20160011470/downloads/20160011470.pdf",label:"NASA Technical Reports Server — reusable cislunar transportation architecture"}]
  }),

  [r102.slug]: requirementArticle(r102,{
    shortTitle:"heavy cislunar freight-tug requirement",
    lead:"O-102 was the Deep-Space Century requirement for a heavy cislunar freight carrier and tug. It moved cargo between orbital yards, depots, stations, and lunar destinations without repeatedly carrying Earth-return structure. The developed concept could take the form of a propulsion and control spine with exposed modular cargo fixtures.",
    canonRole:"heavy cislunar freight and tug role",
    canonOpen:"<!-- altwwii-writer-block:start id=wb-g-20260816-o2b6f writer=g kind=revision created=2026-08-16T10:10:00-06:00 -->Moderate thrust, high efficiency, and a truss-like modular configuration are extrapolated guidance rather than a final specification.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    complements:[{href:"o-103-propellant-tanker-depot-tender.html",kicker:"Propellant support",label:"O-103 Tanker and Depot Tender"},{href:"o-106-orbital-construction-yard-tender.html",kicker:"Yard complement",label:"O-106 Construction Tender"}],
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>O-102 reserved the movement of large cargoes through cislunar space. It was both carrier and tug: a reusable propulsion unit could take responsibility for loads that lacked independent navigation, power, or transfer capability.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The vehicle served transport legs beginning and ending in space. Surface launch, atmospheric entry, and lunar landing equipment belonged to other systems or to the payload itself.</p>"},
      {id:"cargo-system",title:"Cargo system",html:"<p>The developed concept resembles a flying truss with cargo fixtures. Tanks, pressure modules, construction packages, station sections, and standardized containers could be attached around the load-bearing spine. The control and propulsion section remained reusable while cargo sets changed between missions.</p><p>External carriage simplified access and allowed loads larger than an enclosed bay. It exposed cargo to vacuum, radiation, thermal cycling, debris, and plume contamination. Pressure-sensitive or temperature-controlled goods therefore required their own protective container.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"cargo-classes",title:"Cargo classes",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Load class</th><th>Handling requirement</th><th>Likely destination</th></tr></thead><tbody><tr><td>Standard freight containers</td><td>Mechanical restraint, power or thermal connection where required</td><td>Stations, depots, lunar terminals</td></tr><tr><td>Pressure modules</td><td>Leak protection, controlled attitude, verified docking ring</td><td>Habitation and laboratory complexes</td></tr><tr><td>Propellant tanks</td><td>Thermal control, valve isolation, hazardous separation</td><td>O-103 depots and deep-space stages</td></tr><tr><td>Structural assemblies</td><td>Multiple grapple points and bending-load limits</td><td>Yards and construction sites</td></tr><tr><td>Disabled vehicles</td><td>Temporary power, attitude stabilization, uncertain mass properties</td><td>Repair yard or disposal orbit</td></tr><tr><td>Bulk consumables</td><td>Inventory seals and contamination control</td><td>Long-duration facilities</td></tr></tbody></table></div><p>The categories express the freight-tug requirement. They do not fix an accepted container standard or imply that one O-102 configuration carried every load.</p>"},
      {id:"structure",title:"Structure and attachment",html:"<p>A central spine would carry thrust, docking, avionics, utilities, and the principal load paths. Cargo fittings needed positive capture, electrical bonding, data identification, and inspection access. Loads projecting beyond the spine required clearance for docking approaches, radiators, sensors, and attitude-control plumes.</p><p>Attachment standards, container dimensions, truss material, load rating, and the division between permanent and exchangeable structure remain open.</p>"},
      {id:"mass-balance",title:"Mass properties and thrust alignment",html:"<p>Changing cargoes altered total mass, center of mass, rotational inertia, structural bending, and the response to attitude-control inputs. Mission preparation therefore required a certified load plan and a vehicle-control model for each assembled stack.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Paired cargo positions could preserve the American preference for bilateral arrangement. Irregular loads might require asymmetric placement, ballast, adjustable engine alignment, or distributed control thrusters. The crew or automatic guidance system had to prevent flexible loads from producing damaging oscillation during a burn.</p>"},
      {id:"propulsion",title:"Propulsion and routes",html:"<p>The role places moderate thrust beside high propellant efficiency.<sup class='canon-note' data-provenance='e'>[e]</sup> It does not select one engine. Chemical, nuclear-thermal, and later electric variants could answer different routes, provided they remained within the O-102 freight requirement.</p><p>Departure plans balanced cargo mass, propellant, travel time, orbital geometry, engine starts, and the availability of a receiving tug or berth. A load intended for a construction deadline might use a faster transfer than bulk stores sent on a replenishment cycle. O-108 later reserved the freight missions willing to accept very low thrust for still greater efficiency.</p>"},
      {id:"rendezvous",title:"Rendezvous and cargo transfer",html:"<p>The tug could dock directly, berth a load with a manipulator, capture a free-flying pallet, or deliver the complete stack to a yard fixture. Relative navigation and low closing speeds were essential when the payload itself lacked active guidance.</p><p>Before release, the receiving facility would assume power, thermal, pressure, or attitude responsibilities specified for the load. Custody documents, mass records, hazardous-material declarations, and mechanical-release checks accompanied the physical handoff.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"crew",title:"Crew and automation",html:"<p>Routine freight favored automatic navigation, fault monitoring, and docking because cabin provisions consumed mass and many cargoes tolerated long schedules. Crewed operation remained compatible with unusual loads, commissioning flights, repair work, and missions requiring judgment near inhabited structures.</p><p>The requirement does not determine whether the selected vehicle was normally crewed, remotely supervised, autonomous between burns, or produced in separate crewed and uncrewed variants.</p>"},
      {id:"operations",title:"Operating cycle",html:"<p>Freight work divided into load acceptance, assembly, mass-properties verification, departure clearance, transfer, destination rendezvous, unloading, inspection, and return or reassignment. A tug could remain at a depot or yard and take whichever cargo arrived next.</p><p>Inspection concentrated on the propulsion spine, attachment fittings, power and data trunks, docking equipment, and parts exposed to repeated thermal cycles. A damaged or contaminated cargo module could be isolated without retiring the complete tug.</p>"},
      {id:"industrial-role",title:"Industrial role",html:"<p>O-102 made orbital construction and lunar supply less dependent on multipurpose spaceplanes. The requirement connected <a href='liberty-yard.html'>Liberty Yard</a>, <a href='o-103-propellant-tanker-depot-tender.html'>propellant depots</a>, <a href='o-106-orbital-construction-yard-tender.html'>construction tenders</a>, and destination operators in one freight system.</p><p>Commercial carriers and industrial consortia later issued their own tug and container requirements. The federal O-102 number could remain important for military or protected cargo even after commercial freight exceeded federal traffic.</p>"},
      {id:"status",title:"Program status",html:openRegister(r102,"The truss-and-fixtures concept and moderate-thrust emphasis do not establish a production configuration.")}
    ],
    sources:[{href:"https://ntrs.nasa.gov/api/citations/19710011978/downloads/19710011978.pdf",label:"NASA Technical Reports Server — reusable space-tug and cislunar transportation study"},{href:"https://ntrs.nasa.gov/api/citations/20160011470/downloads/20160011470.pdf",label:"NASA Technical Reports Server — reusable cislunar transportation architecture"}]
  }),

  [r103.slug]: requirementArticle(r103,{
    shortTitle:"propellant-tanker and depot-tender requirement",
    lead:"O-103 was the Deep-Space Century requirement for an orbit-resident propellant tanker and depot tender. Its purpose was to make fuel storage, transfer, inspection, and delivery an independent transportation service rather than a secondary feature of passenger stations or general cargo vehicles.",
    canonRole:"propellant tanker and depot-tender role",
    canonOpen:"<!-- altwwii-writer-block:start id=wb-g-20260816-o3c7g writer=g kind=revision created=2026-08-16T10:10:00-06:00 -->The extrapolated register fixes the infrastructure function within its own scheme but does not select propellant types, tankage, transfer rates, depot ownership, or operational chronology.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    complements:[{href:"o-8-orbital-tanker.html",kicker:"Runway-to-orbit predecessor",label:"O-8 Orbital Tanker"},{href:"o-102-heavy-cislunar-freight-tug.html",kicker:"Principal customer",label:"O-102 Freight Tug"}],
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>O-103 carried propellant to vehicles and tended fixed or movable depots. The program acknowledged that cislunar transport depended upon fuel handling as a network in its own right.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The same number joined two related functions. A tanker moved a commodity between points; a tender inspected, conditioned, connected, measured, and maintained the storage and transfer plant that allowed the commodity to be used.</p>"},
      {id:"precedent",title:"O-8 precedent",html:"<p>The <a href='o-8-orbital-tanker.html'>O-8</a> brought propellant from Earth while retaining runway-to-orbit equipment. O-103 served the next stage: transfer and depot work among vehicles and facilities already in space. The two requirements could overlap at low Earth orbit.</p><p>Removal of atmospheric equipment allowed larger tanks, more insulation, longer loiter, additional pumps and couplings, and permanent maintenance access. It did not eliminate the thermal and fluid-management problems of holding propellant in microgravity.</p>"},
      {id:"functions",title:"Tanker and tender functions",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Function</th><th>Principal equipment or procedure</th></tr></thead><tbody><tr><td>Bulk delivery</td><td>Storage tanks, transfer lines, pumps or pressure feed, receiving connection</td></tr><tr><td>Depot tending</td><td>Inspection sensors, manipulators, spares, line and valve service</td></tr><tr><td>Thermal support</td><td>Insulation inspection, shielding, refrigeration or cooling connection</td></tr><tr><td>Tank exchange</td><td>Grapples, structural restraints, utility disconnects, mass verification</td></tr><tr><td>Fuel quality</td><td>Sampling, contamination checks, temperature and pressure records</td></tr><tr><td>Emergency supply</td><td>Protected reserve, priority dispatch, compatible contingency fittings</td></tr></tbody></table></div><p>The table describes the requirement envelope. The current record does not establish whether one hull performed every function or whether the program used several mission modules.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"configuration",title:"Configuration",html:"<p>A compatible tanker form placed insulated tanks close to the vehicle's longitudinal load path and kept propulsion, radiators, docking gear, and servicing access clear of transfer plumbing. A tender could carry work lights, cameras, leak-detection equipment, manipulators, replacement valves, portable lines, and power or cooling jumpers.</p><p>Paired tanks suited American bilateral arrangement and simplified mass balance when drawn down together. Tank number, pressure regime, transfer machinery, crew cabin, manipulator fit, and the division between fixed and exchangeable tanks remain open.</p>"},
      {id:"propellants",title:"Propellant classes",html:"<p>The requirement could encounter cryogenic hydrogen and oxygen, storable maneuvering propellants, and inert feedstocks for electric propulsion. Their storage temperatures, materials, seals, contamination limits, and transfer procedures differed. A universal tank and coupling were therefore unlikely, although shared mechanical and data interfaces remained possible.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The final supported propellant set remains open. The article does not imply that a single O-103 vehicle carried oxidizer, hydrogen, toxic storables, and electric-propulsion feedstock simultaneously.</p>"},
      {id:"cryogenic",title:"Cryogenic management",html:"<p>Hydrogen and oxygen absorbed environmental heat during storage. Insulation, sun shielding, attitude, tank supports, line penetrations, active cooling, pressure control, and management of vapor and liquid location all affected losses and transfer readiness. Long loiter made these functions part of normal operations rather than launch-day preparation.</p><p>Microgravity transfer required the system to acquire liquid rather than vapor, chill lines and the receiving tank, control pressure, detect leakage, and determine the amount remaining. Settling maneuvers, liquid-acquisition devices, pumps, or pressure-fed methods were compatible technical approaches; canon selects none of them.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"sequence",title:"Transfer sequence",html:"<ol><li>Traffic control cleared the servicing geometry and hazardous zone.</li><li>The tanker or tender matched attitude and established a mechanical connection.</li><li>Both vehicles identified the propellant, available volume, pressure, temperature, and custody.</li><li>Lines were checked, conditioned, and configured for the selected transfer method.</li><li>Flow, tank condition, and leakage were monitored throughout transfer.</li><li>Lines were isolated, cleared, disconnected, and inspected before either craft departed.</li></ol><p>This sequence is a procedural extrapolation from the fixed depot-tending role, not an established O-103 flight manual.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"measurement",title:"Measurement and accounting",html:"<p>Custody transfer required measurement, sampling, pressure and temperature records, leak checks, and certification before departure. Delivered mass could not always be inferred from a terrestrial-style level gauge because liquid distribution changed in low gravity.</p><p>Military, federal-commercial, and private fuel could share hardware while remaining separately owned and accounted. The manifest linked source batch, receiving craft, quantity, quality record, reserve status, and any loss during conditioning or transfer.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"safety",title:"Safety and contamination control",html:"<p>Propellant work separated ignition sources, incompatible fluids, crew-transfer routes, and inhabited berths. Isolation valves, remote closure, leak detection, relief paths, emergency undocking, and exclusion zones limited a failure to one tank or connection.</p><p>A tender inspecting a damaged depot had to determine whether the hazard was leakage, overpressure, loss of cooling, contamination, structural damage, or faulty instrumentation before connecting repair equipment. Detailed Aerospace Force standards and accident history remain open.</p>"},
      {id:"network",title:"Cislunar fuel network",html:"<p>O-103 supported <a href='o-101-cislunar-dispatch-craft.html'>dispatch craft</a>, <a href='o-102-heavy-cislunar-freight-tug.html'>freight tugs</a>, rescue vehicles, patrol craft, construction tenders, and deep-space departures. Depots allowed fuel deliveries and vehicle departures to occur on different schedules and gave emergency traffic access to a protected reserve.</p><p>Depot locations, ownership, reserve rules, emergency access, lunar-derived propellant, and the balance between fixed stores and mobile tankers remain open.</p>"},
      {id:"status",title:"Program status",html:openRegister(r103,"The archive records no selected tanker form, depot class, or fuel standard.")}
    ],
    sources:[{href:"https://ntrs.nasa.gov/citations/19890019164",label:"NASA Technical Reports Server — COLD-SAT cryogenic storage, acquisition, and transfer"},{href:"https://ntrs.nasa.gov/citations/20120009208",label:"NASA Technical Reports Server — long-duration cryogenic propellant storage and transfer"}]
  }),

  [r104.slug]: requirementArticle(r104,{
    shortTitle:"deep-space rescue and recovery requirement",
    lead:"O-104 was the Deep-Space Century requirement for rescue, recovery, and assistance beyond the normal reach of atmospheric orbital aircraft. It extended the O-5 Ranger servicing concept into an orbit-resident vehicle able to carry endurance, docking, towing, medical, and repair capability without reserving mass for Earth return.",
    canonRole:"deep-space rescue and recovery role",
    canonOpen:"<!-- altwwii-writer-block:start id=wb-g-20260816-o4d8h writer=g kind=revision created=2026-08-16T10:10:00-06:00 -->Its description as the Ranger concept without atmospheric compromises belongs to the extrapolated scheme; response radius, readiness, crew, equipment, and final vehicle are open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    complements:[{href:"ov-5a-ranger.html",kicker:"Operational predecessor",label:"O-5A Ranger"},{href:"interbloc-space-safety-standards.html",kicker:"Legal setting",label:"Interbloc Space-Safety Standards"}],
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>O-104 reserved deep-space rescue and recovery. The vehicle had to reach a disabled craft, sustain survivors, stabilize or tow the casualty, and support repair or abandonment decisions beyond ordinary station response distance.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The requirement addressed incidents in high Earth orbit, lunar routes, and other cislunar or deep-space operations. It did not promise a rescue from every trajectory or a fixed maximum radius.</p>"},
      {id:"ranger",title:"Ranger inheritance",html:"<p>The <a href='ov-5a-ranger.html'>O-5A Ranger</a> performed satellite servicing, retrieval, and orbital rescue while remaining an atmospheric aircraft. O-104 retained that service identity and removed the need for wings, reentry protection, and runway recovery.</p><p>Ranger experience supplied rendezvous procedure, visual inspection, capture, towing, pressure transfer, tool control, and coordination between pilots, traffic authorities, medical teams, and the owner of a disabled craft. O-104 extended endurance, propellant, stores, and survivor capacity.</p>"},
      {id:"casualties",title:"Casualty classes",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Casualty</th><th>Immediate problem</th><th>Possible O-104 action</th></tr></thead><tbody><tr><td>Loss of propulsion</td><td>Uncontrolled or unsuitable trajectory</td><td>Stabilize, tow, or transfer crew</td></tr><tr><td>Loss of power</td><td>Declining life support and communications</td><td>Supply power, batteries, heat rejection, or refuge</td></tr><tr><td>Pressure failure</td><td>Limited habitable volume and consumables</td><td>Dock, provide pressure transfer, receive survivors</td></tr><tr><td>Navigation or control failure</td><td>Inaccurate ephemeris or hazardous attitude</td><td>Track, inspect, establish relative navigation, control motion</td></tr><tr><td>Medical emergency</td><td>Patient requires treatment or rapid movement</td><td>Deliver medical team, stabilize, evacuate</td></tr><tr><td>Collision damage</td><td>Debris, leakage, structural uncertainty</td><td>Survey at stand-off range, isolate hazards, recover crew</td></tr></tbody></table></div><p>These categories describe planning cases compatible with the fixed rescue mission. They are not a record of O-104 incidents.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"alert",title:"Alert and basing",html:"<p>A rescue vehicle could only shorten the response if it was fueled, provisioned, crewed or remotely ready, and located on a useful trajectory. Basing near a depot, yard, station, or common transfer route reduced preparation time for some casualties and increased it for others.</p><p>Standby planning therefore linked the vehicle to traffic forecasts, known crewed missions, solar conditions, depot reserves, available launch windows, and the survival time reported by the casualty. Readiness posture, number of vehicles, bases, and watch organization remain open.</p>"},
      {id:"response",title:"Intercept planning",html:"<p>Deep-space rescue depends upon departure energy, route geometry, available propellant, casualty trajectory, navigation accuracy, and crew survival time. The craft had to meet the casualty with enough propellant and consumables left to complete a useful recovery.</p><p>Mission control would compare direct intercept, a depot stop, dispatch of an O-101 with personnel or parts, use of a commercial craft, and instructions for the casualty to alter its own trajectory. A fast departure could be counterproductive if it exhausted the reserve needed to brake, match velocity, tow, or return.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"approach",title:"Approach and inspection",html:"<p>The disabled craft might be tumbling, venting fluid, transmitting incomplete data, or surrounded by debris. O-104 therefore required long-range optical and radar observation, relative-navigation sensors, protected communications, and the ability to hold position before committing to close approach.</p><p>Inspection established structural condition, pressure, thermal state, propellant leakage, electrical hazards, docking-port availability, and the motion of the casualty. Grappling or docking began only after the rescue crew selected a safe axis and agreed upon control authority.</p>"},
      {id:"survivors",title:"Survivor transfer and medical support",html:"<p>Survivors could move through a compatible docking connection, a temporary pressure tunnel, or suited transfer. The rescue craft needed spare breathing gas, water, carbon-dioxide removal, restraint positions, sanitation capacity, medical stores, and a pressure refuge separated from damaged equipment.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The number and condition of survivors governed whether O-104 served as a treatment space, temporary shelter, or evacuation vehicle. The current record fixes no medical staff, hospital module, or survivor capacity.</p>"},
      {id:"equipment",title:"Recovery equipment",html:"<p>Compatible equipment included docking adapters, grapples, tow fittings, pressure-transfer gear, emergency life support, medical stores, inspection sensors, power jumpers, data links, patch materials, cutting and fastening tools, and portable attitude-control equipment.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Equipment would be modular because a pressure casualty, disabled tug, drifting passenger vehicle, and damaged reactor craft presented different hazards. No complete carried-equipment table, manipulator arrangement, or mission-module set is established.</p>"},
      {id:"tow",title:"Stabilization and towing",html:"<p>Before towing, the rescue craft had to stop dangerous rotation, establish the combined center of mass, isolate leaking lines, and identify structure able to transmit load. A rigid dock, bridle, tow frame, or controlled formation could be used depending upon the casualty.</p><p>The joined vehicles required new guidance limits. Engine thrust, flexible motion, plume impingement, weak structure, and a shifting load could restrict acceleration. Recovery to a yard or safe orbit might take longer than survivor evacuation.</p>"},
      {id:"repair",title:"Repair, salvage, and abandonment",html:"<p>A mission could restore power or control, replace a component, tow the craft to a yard, remove survivors and records, recover hazardous or classified equipment, move the casualty away from traffic, or mark it for later salvage. Repair in place was favored when the fault was known and the structure remained safe.</p><p>Abandonment remained a planned outcome when approach endangered the rescue crew, the trajectory could not be matched in time, or the damaged vehicle could not survive towing. The requirement does not imply that every hull or payload would be recovered.</p>"},
      {id:"coordination",title:"Coordination and jurisdiction",html:"<p>Distress frequencies, beacons, docking adapters, launch notification, debris warnings, and aid to stranded crews were already part of the <a href='interbloc-space-safety-standards.html'>interbloc safety order</a>. O-104 supplied an American vehicle requirement inside that shared legal and operational environment.</p><p>Traffic control, the Aerospace Force, the casualty's owner, insurers, station authorities, medical officers, and foreign governments could all have an interest in one incident. Immediate protection of life did not automatically settle later custody, salvage, investigation, or liability.</p>"},
      {id:"status",title:"Program status",html:openRegister(r104,"No response unit, fixed base, or operational rescue has been selected in canon.")}
    ],
    sources:[{href:"https://www.nasa.gov/reference/safety-history-contingency-mishaps/",label:"NASA — deep-space crew survivability and contingency planning"},{href:"https://www.nasa.gov/wp-content/uploads/2023/10/nasa-satellite-servicing-project-report-0511.pdf",label:"NASA — satellite servicing, rendezvous, and proximity operations"}]
  }),

  [r105.slug]: requirementArticle(r105,{
    shortTitle:"cislunar patrol and inspection requirement",
    lead:"O-105 was the Deep-Space Century requirement for an orbit-resident military patrol and inspection craft. It carried the surveillance, approach, identification, and maneuver functions of Project Zenith into cislunar space while abandoning the assumption that the vehicle must return through the atmosphere.",
    canonRole:"cislunar patrol and inspection role as the orbit-resident military successor to Zenith",
    canonOpen:"<!-- altwwii-writer-block:start id=wb-g-20260816-o5e9i writer=g kind=revision created=2026-08-16T10:10:00-06:00 -->The extrapolated scheme makes maneuver authority important and permits a heavily instrumented form; armament, rules of engagement, sensors, and production status remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    complements:[{href:"project-zenith.html",kicker:"Atmospheric predecessor",label:"Project Zenith"},{href:"american-orbital-combat-aircraft.html",kicker:"Later combat register",label:"American Orbital Combat Aircraft"}],
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>O-105 reserved patrol, inspection, and military presence through cislunar space. It was the O-Hundred requirement most directly connected to the Aerospace Force's protected-navigation and orbital-security missions.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The requirement applied to a craft based in space. It exchanged runway alert and atmospheric return for endurance, propellant, sensors, and repeated maneuver among orbital facilities and transfer routes.</p>"},
      {id:"zenith",title:"Zenith inheritance",html:"<p><a href='project-zenith.html'>O-7A Zenith</a> supplied rapid launch, interception, electronic warfare, protected navigation, and an internal mission bay. O-105 moved the patrol function away from Earth-runway responsiveness and toward sustained basing in space.</p><p>Zenith crews and controllers provided experience in target tracking, orbit matching, communications discipline, inspection authorization, electronic support, and the distinction between an intercept and an attack. O-105 did not have to preserve Zenith's lifting body, air-breathing ascent, or conventional reentry capability.</p>"},
      {id:"missions",title:"Mission categories",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Mission</th><th>Purpose</th><th>Typical constraint</th></tr></thead><tbody><tr><td>Route patrol</td><td>Observe traffic and maintain a federal presence</td><td>Endurance and broad sensor coverage</td></tr><tr><td>Identification</td><td>Resolve an uncertain track or inactive transponder</td><td>Accurate relative navigation</td></tr><tr><td>Close inspection</td><td>Document configuration, damage, or prohibited equipment</td><td>Controlled approach and collision avoidance</td></tr><tr><td>Escort</td><td>Accompany protected or hazardous traffic</td><td>Schedule and maneuver reserve</td></tr><tr><td>Electronic support</td><td>Characterize communications, radar, and interference</td><td>Recording, direction finding, and legal authority</td></tr><tr><td>Contingency presence</td><td>Support a crisis, seizure, evacuation, or rescue</td><td>Command authorization and interoperable equipment</td></tr></tbody></table></div><p>The categories express the fixed patrol and inspection role. They do not establish a published operational history.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"maneuver",title:"Maneuver and rendezvous",html:"<p>Maneuver authority matters because inspection requires matching an object's orbit, controlling approach geometry, and retaining the ability to disengage.<sup class='canon-note' data-provenance='e'>[e]</sup> An intercept plan had to account for relative velocity, lighting, communications delay, propellant reserve, possible evasive motion, and a collision-avoidance departure.</p><p>The final propulsion balance between rapid burns and long-duration economy is open. A patrol craft could not treat every detected object as immediately reachable; orbital plane and timing governed the cost of an approach.</p>"},
      {id:"sensors",title:"Sensors and identification",html:"<p>A heavily instrumented configuration is compatible with the requirement. Optical and infrared cameras, radar, radio-frequency receivers, navigation sensors, range and closing-rate instruments, and close-inspection systems could identify objects and document behavior.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Identification combined remote observations with traffic records, transponder replies, declared mission, maneuver history, and comparison against known vehicle geometry. No sensor suite, recognition standard, or electronic-intelligence fit is fixed.</p>"},
      {id:"inspection",title:"Inspection procedure",html:"<p>A normal inspection progressed from remote tracking to communications challenge, cooperative rendezvous, a defined hold point, and controlled movement around the subject. Relative-navigation systems measured bearing, range, attitude, rotation, and closing rate while the patrol crew maintained an escape direction.</p><p>Close imagery recorded markings, ports, antennas, payload structures, damage, leakage, and other visible conditions. Physical contact, docking, entry, or seizure required authority beyond ordinary observation. Detailed inspection law and challenge phrases remain open.</p>"},
      {id:"crew",title:"Crew and endurance",html:"<p>Patrol work required flight control, sensor operation, communications, mission command, and maintenance. These duties could be combined among a small crew and supplemented by automation. Cabin, crew size, watch system, and mission duration remain unselected.</p><p>An orbit-resident craft needed replenishable life support, sleeping and sanitation arrangements, radiation refuge, medical stores, and access to machinery for inspections between patrols. Docking at a station or tender could support longer deployments than the vehicle's independent endurance.</p>"},
      {id:"communications",title:"Communications and records",html:"<p>O-105 required protected command links, traffic-control channels, interbloc distress frequencies, identification exchange, and a complete time-stamped record of sensor data and crew actions. A patrol beyond immediate ground contact also needed standing rules for collision avoidance and protection of life.</p><p>Evidence gathered during an inspection could support diplomatic protest, safety action, treaty review, salvage proceedings, or military planning. The requirement does not determine who held final legal custody of those records.</p>"},
      {id:"weapons",title:"Armament and restraint",html:"<p>Patrol and inspection do not by themselves establish armament. The mature orbital order distinguishes observation, approach, interference, seizure, disabling, and destructive attack. O-105 weapon carriage and rules of engagement remain open.</p><p>Defensive aids, warning devices, electronic countermeasures, grapples, or small guided weapons are technically compatible possibilities; none is canonically selected. The article should not be used to convert a surveillance requirement into a confirmed armed class.</p>"},
      {id:"service",title:"Service relationship",html:"<p>The vehicle belonged to the Aerospace Force's orbit-resident military mission. It could operate beside commercial traffic, rescue authorities, depots, and the <a href='interbloc-space-safety-standards.html'>interbloc safety order</a> while remaining a federal military craft.</p><p>After 2000, purpose-built <a href='american-orbital-combat-aircraft.html'>orbital combat aircraft</a> separated fighter, attack, and bomber missions from the older O-series utility register. O-105 remained the conceptual bridge between Zenith's armed inspection work and that later combat category. Unit structure and readiness posture are unselected.</p>"},
      {id:"status",title:"Program status",html:openRegister(r105,"The patrol role does not prove that a production craft or armed class entered service.")}
    ],
    sources:[{href:"https://www.nasa.gov/isam/relative-navigation-system/",label:"NASA — relative navigation for autonomous spacecraft servicing"},{href:"https://www.nasa.gov/reference/jsc-rendezvous-prox-ops-docking-subsystems/",label:"NASA Johnson — rendezvous, proximity operations, docking, and collision avoidance"}]
  }),

  [r106.slug]: requirementArticle(r106,{
    shortTitle:"orbital construction and yard-tender requirement",
    lead:"O-106 was the Deep-Space Century requirement for orbital construction, assembly, welding, manipulation, maintenance, and yard support. It treated the spacecraft yard as an operating environment requiring purpose-built mobile machinery rather than a station to be served only by adapted spaceplanes and suited workers.",
    canonRole:"orbital construction and yard-tender role",
    canonOpen:"<!-- altwwii-writer-block:start id=wb-g-20260816-o6f1j writer=g kind=revision created=2026-08-16T10:10:00-06:00 -->The extrapolated register fixes the assembly, welding, manipulation, and maintenance mission within its own scheme; tool fit, autonomy, crew, yard assignments, and vehicle form remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    complements:[{href:"liberty-yard.html",kicker:"Principal federal yard",label:"Liberty Yard"},{href:"american-spacecraft-manufacturing-industry.html",kicker:"Industrial system",label:"American Spacecraft Manufacturing Industry"}],
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>O-106 reserved a specialized tender for assembly, welding, manipulation, and maintenance at orbital yards.<sup class='canon-note' data-provenance='e'>[e]</sup> It could move between work sites and support structures too large or awkward for fixed station equipment.</p><p>The requirement treated a yard as an operating environment. Large spacecraft assembled in orbit needed mobile handling, alignment, inspection, utilities, and repair machinery throughout construction and after commissioning.</p>"},
      {id:"yard-work",title:"Yard work",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Work category</th><th>Representative task</th><th>Principal control problem</th></tr></thead><tbody><tr><td>Structural assembly</td><td>Position trusses, beams, frames, and pressure sections</td><td>Alignment and low-force capture</td></tr><tr><td>Tank and radiator installation</td><td>Move large fragile components into prepared fittings</td><td>Clearance, thermal surfaces, and bending loads</td></tr><tr><td>Utility integration</td><td>Route and connect power, data, fluid, and thermal lines</td><td>Identification, cleanliness, and leak control</td></tr><tr><td>Inspection</td><td>Image joints, verify dimensions, test continuity and pressure</td><td>Traceable records and independent acceptance</td></tr><tr><td>Maintenance</td><td>Remove failed modules and install replacements</td><td>Isolation of the operating vehicle</td></tr><tr><td>Salvage</td><td>Stabilize and dismantle damaged structures</td><td>Unknown mass properties and debris</td></tr></tbody></table></div><p>The tasks follow from the fixed construction and maintenance role. Exact processes and tool qualification remain open.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"configuration",title:"Configuration",html:"<p>A compatible tender combined a pressure cabin or control section, low-speed translation and attitude propulsion, articulated manipulators, equipment racks, cameras, work lights, power and data outlets, tool storage, and standardized grapple points. Its structure emphasized visibility and access around a load rather than an enclosed cargo bay.</p><p>The tender could carry removable work packages for welding, inspection, tank handling, line installation, or salvage. Hull form, arm arrangement, crew cabin, payload mass, and the number of mission modules remain open.</p>"},
      {id:"manipulation",title:"Manipulation systems",html:"<p>The mission favored articulated arms, cameras, force and torque sensing, restraint fixtures, end-effectors, and low-speed translation control.<sup class='canon-note' data-provenance='e'>[e]</sup> A manipulator had to distinguish intended contact from an impact and prevent a captured component from driving the tender into the work site.</p><p>Tools could be exchanged at a rack or passed to a suited worker. Prepared structures carried grapple fixtures, visual targets, utilities, and access clearances. Legacy or damaged objects required slower survey and improvised capture. The archive does not select the number, reach, or load rating of any arm.</p>"},
      {id:"stationkeeping",title:"Stationkeeping and load control",html:"<p>Construction loads often had large inertia and flexible members. The control system had to account for the combined tender, manipulator, and payload rather than treating the arm as a massless tool. Thruster firings near open tanks, radiators, optical surfaces, or suited crews required plume limits.</p><p>The tender could brace against a yard fixture, free-fly beside the work, or attach itself to the structure. Each method changed the allowable force, pointing accuracy, and collision response.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"work-methods",title:"Crew and remote operation",html:"<p>Construction work could combine an onboard crew, remote manipulators, external suited workers, automatic stationkeeping, and control from a yard operations room. The balance among them depended upon communications delay, visibility, task complexity, hazard, and the consequence of an error.</p><p>Crews required operator stations with several camera views, force feedback or load displays, procedures for tool custody, and a rapid means to safe the arms. Suited workers needed restraint points and a defined refuge if the tender or work site lost power.</p>"},
      {id:"joining",title:"Joining and inspection",html:"<p>Assembly could use mechanical fasteners, prepared latches, electrical bonding, fluid couplings, and qualified welding or brazing processes. Thermal distortion, contamination, residual stress, trapped gas, and inaccessible joints complicated work in vacuum.</p><p>Inspection followed each critical joint. Cameras, dimensional targets, electrical tests, leak checks, radiography or other nondestructive methods could establish acceptance before the next load concealed the work.<sup class='canon-note' data-provenance='e'>[e]</sup> No O-106 welding system or inspection code is fixed.</p>"},
      {id:"tooling",title:"Power, tools, and consumables",html:"<p>The tender supplied regulated electrical power, data, lighting, cooling, and storage for tools, fasteners, seals, cable, line, patch material, and protective covers. Some work packages could take power from the yard while remote jobs required the tender's own supply.</p><p>Tool control mattered because a released object became a collision hazard. Every item used outside the cabin required a tether, capture feature, inventory entry, or recovery plan.</p>"},
      {id:"safety",title:"Safety and certification",html:"<p>Work around pressure vessels, propellant lines, reactors, radiators, magazines, and inhabited modules required isolation zones, positive system identification, tool control, collision limits, and independent inspection.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Construction authority could stop traffic through the work volume, inhibit thrusters, isolate power and fluid systems, and order evacuation of nearby compartments. Formal certification offices, work permits, accident history, and the division between military and civil inspection remain unselected.</p>"},
      {id:"industrial-context",title:"Industrial context",html:"<p><a href='liberty-yard.html'>Liberty Yard</a> assembled Pilgrim and later large structures. Corporate yards and station operators expanded after 1990. O-106 defined a federal service vehicle inside an industry increasingly shared with private customers.</p><p>The same mechanical interfaces benefited <a href='american-spacecraft-manufacturing-industry.html'>manufacturers</a>, commercial tugs, depot tenders, and salvage craft. A company could operate its own construction machinery while the Aerospace Force retained O-106 for protected work and military yards.</p>"},
      {id:"status",title:"Program status",html:openRegister(r106,"No tender layout, construction unit, or completed vehicle is established.")}
    ],
    sources:[{href:"https://www.nasa.gov/isam/",label:"NASA — in-space servicing, assembly, and manufacturing"},{href:"https://etd.gsfc.nasa.gov/capabilities/in-space-servicing-assembly-and-manufacturing/",label:"NASA Goddard — robotic servicing, force sensing, prepared interfaces, and simulation"}]
  }),

  [r107.slug]: requirementArticle(r107,{
    shortTitle:"long-duration scientific-survey requirement",
    lead:"O-107 was the Deep-Space Century requirement for a long-duration scientific survey craft. Its reserved operating field included asteroids, high lunar space, the wider Earth–Moon system, and planetary reconnaissance. It combined mobile instruments and endurance in a vehicle intended to remain away from Earth for extended missions.",
    canonRole:"long-duration scientific survey role across asteroid, high-lunar, Earth–Moon, and planetary reconnaissance missions",
    canonOpen:"<!-- altwwii-writer-block:start id=wb-g-20260816-o7g2k writer=g kind=revision created=2026-08-16T10:10:00-06:00 -->The number and survey role are extrapolated; destinations, crew status, instruments, propulsion, contractors, and mission record remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    complements:[{href:"o-109-extralunar-endurance-vehicle.html",kicker:"Endurance complement",label:"O-109 Extralunar Endurance Requirement"},{href:"planetary-satellite-system.html",kicker:"Navigation environment",label:"Planetary Satellite System"}],
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>O-107 reserved long-duration survey and reconnaissance beyond routine low-orbit observation. Asteroid, high-lunar, Earth–Moon, and planetary work formed the incorporated mission range.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The requirement joined a reusable spacecraft bus with replaceable scientific payloads. It sought sustained observation, navigation, data return, and instrument support rather than the rapid transport, freight, or patrol functions of neighboring O-Hundred numbers.</p>"},
      {id:"regions",title:"Operating regions",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Region</th><th>Representative survey</th><th>Operational demand</th></tr></thead><tbody><tr><td>High Earth orbit</td><td>Radiation, communications geometry, and distant Earth observation</td><td>Long-period navigation and repeated tracking</td></tr><tr><td>High lunar and libration regions</td><td>Lunar gravity, communications sites, transfer routes</td><td>Changing Earth visibility and lunar perturbations</td></tr><tr><td>Earth–Moon space</td><td>Dust, radiation, traffic, and candidate infrastructure sites</td><td>Wide-area coverage and data relay</td></tr><tr><td>Near-Earth asteroids</td><td>Shape, rotation, composition, mass, and approach hazards</td><td>Autonomous operations near a small irregular body</td></tr><tr><td>Planetary reconnaissance</td><td>Remote sensing and route preparation</td><td>Long communications delay and deep-space endurance</td></tr></tbody></table></div><p>The listed regions define the established envelope. They do not prove that one configuration visited all of them or that any specific O-107 mission flew.</p>"},
      {id:"configuration",title:"Spacecraft bus and payload section",html:"<p>A compatible vehicle separated the durable bus—propulsion, power, communications, navigation, thermal control, data handling, and maintenance access—from a mission payload. External mounting points offered unobstructed fields of view while a protected bay carried sensitive electronics, calibration equipment, or deployable probes.</p><p>Instrument vibration, heat, magnetic cleanliness, radio interference, pointing, and contamination could conflict with propulsion and crew systems. The bus therefore needed defined quiet periods and payload interfaces. Hull form, crew cabin, payload mass, and degree of modularity remain open.</p>"},
      {id:"survey",title:"Survey instruments",html:"<p>Compatible payloads included visible, infrared, and ultraviolet imaging; imaging spectroscopy; radar sounding or altimetry; radio science; gravimetry; magnetometers; plasma and charged-particle instruments; dust detectors; and radiation monitors.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Passive instruments measured existing light, fields, and particles. Active radar or radio experiments transmitted energy and demanded more power, thermal rejection, antenna area, and precise knowledge of the vehicle's position and motion. No definitive instrument package is fixed.</p>"},
      {id:"pointing",title:"Pointing, calibration, and observation",html:"<p>Some instruments could point independently on a platform; others required the complete vehicle to turn. Attitude control had to settle after a maneuver and hold the line of sight while managing flexible antennas, radiators, and booms.</p><p>Calibration used known targets, internal references, dark observations, repeated geometry, and comparison among instruments. Observation planning also accounted for sunlight, eclipse, thermal state, communications windows, and interference from thrusters or transmitters.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"navigation",title:"Navigation and close survey",html:"<p>Mission navigation combined a reference trajectory, determination of the actual orbit, and correction maneuvers. Near an asteroid or other irregular body, weak and uncertain gravity, rotation, surface debris, and incomplete shape knowledge increased the need for optical navigation and autonomous hazard limits.</p><p>Close inspection could proceed through distant characterization, progressively lower or slower passes, stationkeeping, and deployment of beacons or small probes. Landing and sample collection were compatible payload options rather than fixed O-107 requirements.</p>"},
      {id:"data",title:"Communications and data",html:"<p>Survey instruments could produce more data than a distant link returned immediately. The vehicle required onboard storage, prioritization, compression, error correction, scheduled transmission, and a protected engineering channel independent of the principal science downlink.</p><p>Longer range reduced data rate and increased command delay. Antenna pointing had to be coordinated with observations, maneuver, and thermal control. The American tracking and relay network supporting O-107 is not fully identified in the record.</p>"},
      {id:"endurance",title:"Endurance and maintenance",html:"<p>The vehicle required power, thermal control, communications, maintenance access, data storage, radiation tolerance, and fault management suited to missions longer than a spaceplane sortie. Equipment had to enter safe states during communications loss and preserve enough capability to resume an observation plan.</p><p>Replaceable electronics, redundant control paths, accessible instruments, and standard spares extended service. Crewed, intermittently crewed, and automatic arrangements all remain possible.</p>"},
      {id:"crew",title:"Crewed and uncrewed operation",html:"<p>A crew could repair instruments, change observation plans, deploy equipment, and exercise judgment during close survey. It also required habitation, consumables, radiation protection, medical support, and a faster mission schedule. An automatic vehicle could accept slower transfers and longer observations with less mass.</p><p>The requirement could therefore produce different mission modules or variants. No crew complement, human-rating decision, or normal watch organization is fixed.</p>"},
      {id:"payload",title:"Deployed payloads and samples",html:"<p>A modular payload bay or external fixtures could carry navigation beacons, relay packages, impactors, small landers, free-flying inspectors, or sample containers.<sup class='canon-note' data-provenance='e'>[e]</sup> Each added a release, tracking, communications, and planetary-protection problem.</p><p>Sample return required containment and a receiving chain. It is compatible with scientific survey work but is not an established requirement or completed O-107 mission.</p>"},
      {id:"institutions",title:"Institutional use",html:"<p>The O designation places the requirement under the Aerospace Force. Scientific agencies, universities, commercial operators, and foreign partners could supply instruments or investigators, while military offices could use the same bus for route, radiation, and site reconnaissance.</p><p>Payload selection, data rights, foreign participation, classification, and mission scheduling remain open. The article does not assign the vehicle to a civilian agency merely because its principal function was scientific.</p>"},
      {id:"relationship",title:"Relationship to O-109",html:"<p>O-107 defined the scientific-survey function. <a href='o-109-extralunar-endurance-vehicle.html'>O-109</a> later defined a mature vehicle able to remain beyond the Earth–Moon economy for years. A long O-107 survey and an O-109 endurance mission could resemble one another while retaining different procurement purposes.</p>"},
      {id:"status",title:"Program status",html:openRegister(r107,"The stated destinations define a requirement envelope, not a completed mission list.")}
    ],
    sources:[{href:"https://science.nasa.gov/learn/basics-of-space-flight/chapter12-1/",label:"NASA Science — planetary science instruments and active and passive sensing"},{href:"https://science.nasa.gov/learn/basics-of-space-flight/chapter13-1/",label:"NASA Science — spacecraft navigation and trajectory correction"},{href:"https://www.nasa.gov/communicating-with-missions/",label:"NASA — near-space and deep-space communications and navigation"}]
  }),

  [r108.slug]: requirementArticle(r108,{
    shortTitle:"electric-propulsion freighter requirement",
    lead:"O-108 was the Deep-Space Century requirement for a long-haul cargo and tug vehicle built around high-power electric propulsion. It deliberately exchanged acceleration and short journey times for high exhaust velocity, low reaction-mass consumption, and large accumulated changes in velocity over weeks or months.",
    canonRole:"high-efficiency electric-propulsion freight role",
    canonOpen:"<!-- altwwii-writer-block:start id=wb-g-20260816-o8h3l writer=g kind=revision created=2026-08-16T10:10:00-06:00 -->Its slow departure, long acceleration, cargo-spine concept, and reactor–radiator–thruster integration are extrapolated requirements; name, power level, thruster type, payload, chronology, and service status remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    complements:[{href:"american-nuclear-electric-propulsion.html",kicker:"Power and propulsion",label:"American Nuclear-Electric Propulsion"},{href:"american-ion-propulsion.html",kicker:"Thruster lineage",label:"Ion Propulsion in the United States"}],
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>O-108 reserved deep freight for cargo whose schedule allowed propulsion efficiency to dominate. The vehicle could spend days spiraling out of orbit, weeks building velocity, and months on a transfer completed faster by a crewed craft.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The requirement made sustained low thrust the normal means of transportation. Electric propulsion was no longer an auxiliary for stationkeeping or a laboratory payload; it sized the power, thermal, structure, navigation, and cargo system.</p>"},
      {id:"architecture",title:"Architecture",html:"<p>The developed concept places reactor, power conversion, radiators, propellant, electric thrusters, avionics, and automatic cargo fixtures around a structural spine. It resembles neither a spaceplane nor a sealed passenger ship. The propulsion and power sections could remain in service while loads changed.</p><p>Distance between the reactor, crew-accessible equipment, electronics, and cargo allowed shielding by separation and local mass. Long radiators and power cables introduced flexible structures and failure points. Exact symmetry, tank arrangement, shielding, cargo standard, and crew provision remain open.</p>"},
      {id:"propulsion",title:"Electric propulsion",html:"<p>Electric thrusters ionize or otherwise electrically accelerate a propellant to high exhaust velocity. The reaction mass is used efficiently, while the force produced at any instant remains small. Continuous operation over long periods accumulates useful velocity change.</p><p>O-108 therefore favored patient cargo. The vehicle could begin thrusting well before a high-thrust freighter departed and still arrive later, but with a different ratio of payload and reaction mass. Thruster family, exhaust velocity, thrust, and total installed number are unselected.</p>"},
      {id:"system",title:"Power and propulsion system",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Element</th><th>Function</th><th>Principal design issue</th></tr></thead><tbody><tr><td>Reactor</td><td>Supply long-duration thermal power</td><td>Control, shielding, fuel life, decay heat</td></tr><tr><td>Power conversion</td><td>Turn reactor heat into electricity</td><td>Efficiency, bearings or working fluid, redundancy</td></tr><tr><td>Distribution</td><td>Condition and route power to thrusters and vehicle loads</td><td>Voltage control, switching, insulation, fault isolation</td></tr><tr><td>Thrusters</td><td>Accelerate reaction mass</td><td>Electrode or grid life, erosion, plume interaction</td></tr><tr><td>Feed system</td><td>Store and meter propellant</td><td>Purity, flow stability, valve endurance</td></tr><tr><td>Radiators</td><td>Reject unused heat</td><td>Area, orientation, puncture, deployment</td></tr></tbody></table></div><p>The functions are technically necessary to the fixed nuclear-electric direction; no specific O-108 hardware is selected.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"power",title:"Power conversion and distribution",html:"<p>Reactor heat had to pass through conversion machinery before reaching the thrusters as regulated electricity. Pumps, turbines or other conversion equipment, generators, switchgear, transformers or conditioning electronics, cables, and control units formed one propulsion plant.</p><p>Power could be divided among propulsion, communications, payload conditioning, navigation, heaters, and maintenance. Loss of one bus or converter should reduce thrust rather than disable guidance and safing. General Electric and Westinghouse experience in generation and distribution made them as important as the thruster maker.</p>"},
      {id:"thermal",title:"Thermal control",html:"<p>Every inefficiency became heat that had to be stored temporarily or radiated. The radiator system was therefore a principal structure, not decorative appendage. Its area and operating temperature affected reactor output and available thrust.</p><p>Radiators needed clear fields of view, articulation or vehicle-attitude planning, micrometeoroid tolerance, isolation after puncture, and protection from thruster plume and hot cargo. A larger reactor without corresponding heat rejection did not yield a useful propulsion increase.</p>"},
      {id:"cargo",title:"Cargo employment",html:"<p>The vehicle suited non-urgent propellant, machinery, structural components, bulk consumables, replacement modules, construction material, and prepositioned stores.<sup class='canon-note' data-provenance='e'>[e]</sup> Cargo required restraint, thermal classification, radiation limits, and electrical service where applicable.</p><p>Human passengers and urgent cargo remained better suited to high-thrust vehicles such as <a href='o-101-cislunar-dispatch-craft.html'>O-101</a> or Pilgrim-derived systems. O-108 could carry a maintenance crew for part of a mission without becoming a normal passenger transport.</p>"},
      {id:"navigation",title:"Navigation and trajectory control",html:"<p>Continuous or repeated low thrust changed the route throughout the transfer. Mission design specified a thrust history rather than a few burns separated by long coasts. Orbit determination, attitude, propellant flow, electrical power, and thruster health all influenced the achieved trajectory.</p><p>A shutdown changed arrival time and geometry even when it did not immediately endanger the vehicle. Guidance therefore replanned after outages and reserved a terminal phase for rendezvous, braking, and collision avoidance. Detailed control architecture remains open.</p>"},
      {id:"automation",title:"Automation and traffic",html:"<p>Long freight missions favored automatic navigation, power management, fault isolation, and cargo monitoring. Ground or orbital controllers supervised trends and approved major changes while the vehicle handled faster protection functions locally.</p><p>Low-thrust spirals could cross many orbital altitudes and remain in populated regions longer than a high-thrust departure. Traffic coordination required predicted thrust arcs, uncertainty bounds, conjunction screening, and prompt reporting of an interruption.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"maintenance",title:"Maintenance and service life",html:"<p>The economic case depended upon repeated use. Thruster erosion, power-conversion wear, switchgear faults, radiator damage, reactor instrumentation, feed-system contamination, and flexible-structure fatigue therefore mattered as much as one demonstration's efficiency.</p><p>Accessible equipment bays, replaceable thruster modules, isolated radiator loops, redundant power strings, and diagnostic records could support overhaul at an orbital yard. Component life, overhaul interval, and whether reactor replacement was practical remain open.</p>"},
      {id:"industry",title:"Industrial base",html:"<p>Hughes ion-thruster work, Lewis research, General Electric and Westinghouse power machinery, reactor development, and orbital truss fabrication supplied the industrial foundations. Precision thruster grids, power electronics, bearings, reactor fuel, sensors, and high-grade materials continued to come from Earth.</p><p>Final integration could occur in orbit because the complete radiator and truss system did not have to fit one launch vehicle. The O-108 prime contract, integrator, reactor supplier, thruster supplier, and orbital yard are not selected.</p>"},
      {id:"comparison",title:"Relationship to O-102",html:"<p><a href='o-102-heavy-cislunar-freight-tug.html'>O-102</a> reserved moderate-thrust cislunar freight and tug work. O-108 reserved the deeper and slower end of the market, where electric efficiency dominated. A cargo could move on either system depending upon destination, schedule, mass, and available depot service.</p><p>The two numbers denote different requirement centers rather than a legal prohibition on shared components or overlapping routes.</p>"},
      {id:"status",title:"Program status",html:openRegister(r108,"The archive does not establish a completed O-108 craft, though its technical role is more developed than those of several neighboring numbers.")}
    ],
    sources:[{href:"https://www.nasa.gov/space-technology-mission-directorate/tdm/space-nuclear-propulsion/",label:"NASA — nuclear-electric propulsion principles and deep-space applications"},{href:"https://www.nasa.gov/centers-and-facilities/glenn/glenn-history/harold-kaufman/",label:"NASA Glenn — Harold Kaufman and American ion propulsion"},{href:"https://ntrs.nasa.gov/citations/19770032239",label:"NASA Technical Reports Server — Lewis and Hughes 30-centimeter ion-thruster development"}]
  }),

  [r109.slug]: requirementArticle(r109,{
    shortTitle:"extralunar endurance requirement",
    lead:"O-109 was the terminal Deep-Space Century requirement for a mature vehicle intended to operate beyond the Earth–Moon transportation economy. It emphasized years-long endurance, independent repair, stores, power, communications, and mission flexibility rather than a single destination or one rapid expedition.",
    canonRole:"extralunar and deep-space endurance role",
    canonOpen:"<!-- altwwii-writer-block:start id=wb-g-20260816-o9i4m writer=g kind=revision created=2026-08-16T10:10:00-06:00 -->The extrapolated scheme permits years-long absence from Earth but leaves mission, crew, propulsion, configuration, contractor, chronology, and status open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    complements:[{href:"o-107-long-duration-scientific-survey-craft.html",kicker:"Survey complement",label:"O-107 Scientific Survey Requirement"},{href:"deep-space-century.html",kicker:"Requirement context",label:"Deep-Space Century"}],
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>O-109 reserved an endurance vehicle for work beyond the Earth–Moon economy in the 2000s. The requirement defined duration and operating independence more strongly than one destination.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>It was the terminal number of the Deep-Space Century. Earlier O-Hundreds separated dispatch, freight, fuel, rescue, patrol, construction, and survey into mission classes; O-109 asked how a mature spacecraft would remain useful after leaving their normal cislunar support network.</p>"},
      {id:"missions",title:"Mission envelope",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Mission field</th><th>Endurance demand</th><th>Boundary in the record</th></tr></thead><tbody><tr><td>Asteroid operations</td><td>Irregular trajectories, remote survey, prolonged stationkeeping</td><td>No selected asteroid or mission</td></tr><tr><td>Mars-route support</td><td>Months of transit and limited resupply</td><td>No assigned expedition</td></tr><tr><td>Extralunar reconnaissance</td><td>Long communications delay and autonomous operation</td><td>No fixed target</td></tr><tr><td>Infrastructure commissioning</td><td>Carry crew, tools, spares, and local control to a remote site</td><td>No confirmed station</td></tr><tr><td>Technology demonstration</td><td>Operate new power, propulsion, or life-support systems over years</td><td>No selected test article</td></tr></tbody></table></div><p>These are compatible uses of the fixed extralunar endurance role. They are not completed O-109 missions.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"architecture",title:"Endurance architecture",html:"<p>A craft away for years required maintainable life support or autonomous systems, radiation protection, reliable power, redundant communications, fault isolation, stores, and repair capability. Equipment layout had to permit inspection and replacement while the vehicle remained pressurized and operating.</p><p>Endurance did not mean carrying a duplicate of every component. The design could use separated control strings, common replaceable modules, cross-connected utilities, sheltered spares, graceful reduction of nonessential loads, and mission rules for continuing after partial failure.<sup class='canon-note' data-provenance='e'>[e]</sup> The record does not determine whether the accepted vehicle was crewed.</p>"},
      {id:"habitation",title:"Habitation and life support",html:"<p>A crewed configuration required atmosphere revitalization, water recovery, food storage, waste management, hygiene, sleep, exercise, medical care, lighting, privacy, and protection during maintenance or fire. Longer separation from Earth increased the value of recycling and reduced tolerance for equipment that required factory service.</p><p>Habitable volume, recycling rates, gravity arrangement, crew complement, mission duration, and medical capability remain open. An uncrewed O-109 would replace these provisions with additional autonomy, equipment access, and dormant-mode control.</p>"},
      {id:"radiation",title:"Radiation and environmental protection",html:"<p>Beyond low orbit, the vehicle faced solar particle events, long-term cosmic radiation, vacuum, thermal cycling, and micrometeoroids. A storm refuge could concentrate water, food, stores, equipment, and dedicated shielding around a small occupied volume.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Distributed shielding, warning, dosimetry, mission timing, and repairable outer bumpers complemented one another. No shielding material, dose standard, or hull thickness is fixed.</p>"},
      {id:"maintenance",title:"Maintenance and repair",html:"<p>Long absence shifted emphasis from replacement by a nearby yard to onboard diagnosis, accessible machinery, standardized spares, and repair after partial failure. Crew or robots needed safe access to power converters, pumps, valves, filters, electronics, thermal loops, sensors, and communications equipment.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Maintenance planning classified failures by whether they could be isolated, bypassed, repaired, replaced, or tolerated. Machine tools and limited onboard fabrication could produce brackets, covers, ducting, and simple parts; precision electronics, reactor fuel, bearings, and specialist assemblies still came from Earth. Exact philosophy remains open.</p>"},
      {id:"autonomy",title:"Autonomy and fault management",html:"<p>Communications delay and interruption required the vehicle to detect faults, safe equipment, maintain attitude and power, protect the crew or payload, and preserve diagnostic records before ground advice arrived. Automated caretaking also supported periods when a crew was asleep, outside the hull, or absent.</p><p>Human and automatic authority had to be explicit. Some actions could occur immediately to prevent damage; others required crew or ground confirmation because an unnecessary shutdown might end the mission. Software architecture and the extent of robotic maintenance remain unselected.</p>"},
      {id:"stores",title:"Stores and logistics",html:"<p>Mission stores included food, medical material, filters, seals, lubricants, clothing, tools, gases, cleaning supplies, experiment consumables, and replacement modules. Packaging doubled as restraint, shielding, inventory control, and sometimes raw material.</p><p>Long missions required consumption forecasts, protected reserves, shelf-life records, and the ability to find an item after the vehicle's internal arrangement changed. Prepositioned stores or rendezvous with an O-108 freighter were possible but are not fixed parts of an O-109 mission.</p>"},
      {id:"power",title:"Power, propulsion, and thermal control",html:"<p>Years-long missions could use nuclear-electric, nuclear-thermal, chemical, or mixed propulsion depending upon crew time, destination, and cargo. No propulsion school is fixed. The endurance requirement is operational, not a hidden engine designation.</p><p>Power and thermal systems had to support safe mode, communications, life support, heaters, navigation, and maintenance after loss of a principal generator or radiator loop. Reactor use would add shielding, control, decay-heat, and service considerations; solar power would add distance, pointing, and array-area constraints.</p>"},
      {id:"navigation",title:"Navigation and communications",html:"<p>The vehicle required a maintained reference trajectory, independent attitude and time knowledge, orbit determination from available tracking, and the ability to execute correction maneuvers. At long range, command and telemetry schedules replaced the near-continuous conversation possible near Earth.</p><p>High-gain communications, lower-rate emergency links, onboard data storage, message prioritization, and delayed-command review protected the connection home. Antenna or network details and the degree of navigation autonomy remain open.</p>"},
      {id:"crew",title:"Crew organization",html:"<p>If crewed, O-109 needed enough overlapping skill to operate the vehicle after illness, injury, or loss of one specialist. Flight control, engineering, medical care, communications, navigation, science, and repair duties could not each depend upon one person.</p><p>Watch schedules, exercise, workload, isolation, privacy, emergency command, and relations with ground control became design inputs. The current record fixes no crew size, selection program, rank structure, or psychological-support system.</p>"},
      {id:"modules",title:"Mission modules",html:"<p>A durable core could carry mission-specific laboratories, sensor packages, probes, stores, repair shops, or small vehicles. Standard power, data, thermal, structural, and handling interfaces would allow the platform to change purpose between overhauls.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Modularity did not make every payload interchangeable. Cleanliness, radiation, vibration, heat, field of view, and crew safety could require a dedicated arrangement.</p>"},
      {id:"relationship",title:"Relationship to O-107 and O-108",html:"<p><a href='o-107-long-duration-scientific-survey-craft.html'>O-107</a> reserved long-duration scientific survey, while <a href='o-108-electric-propulsion-freighter.html'>O-108</a> reserved efficient deep freight. O-109 asked for a mature endurance platform beyond the cislunar economy. Payload, propulsion, and support hardware might overlap without making the three requirements identical.</p>"},
      {id:"horizon",title:"Status at the canon horizon",html:"<p>The setting record closes on 5 January 2012. Planning, construction, or later mission concepts cannot be presented as completed history unless directly established before that date.</p>"},
      {id:"status",title:"Program status",html:openRegister(r109,"No accepted name, production craft, voyage, or operational unit is established by the canon horizon.")}
    ],
    sources:[{href:"https://www.nasa.gov/humans-in-space/deep-space-habitation-overview/",label:"NASA — deep-space habitation, life support, health, and logistics"},{href:"https://www.nasa.gov/directorates/stmd/space-tech-research-grants/habitats-optimized-for-missions-of-exploration-home/",label:"NASA — autonomous, failure-tolerant, and maintainable deep-space habitats"},{href:"https://www.nasa.gov/integrated-system-for-autonomous-and-adaptive-caretaking-isaac/",label:"NASA — autonomous caretaking for long-duration spacecraft"}]
  })
});

const deepSpaceCentury = window.deepArticles["deep-space-century"];
if (deepSpaceCentury && Array.isArray(deepSpaceCentury.sections)) {
  const registerIndex = deepSpaceCentury.sections.findIndex(section => section.id === "register");
  if (registerIndex >= 0) {
    const rows = deepSpaceRequirementLinks.map(entry => `<tr><td><a href='${entry.slug}.html'>${entry.number}</a></td><td>${entry.label}</td><td>${entry.period}</td></tr>`).join("");
    deepSpaceCentury.sections[registerIndex] = {id:"register",title:"Program register",html:`<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Program</th><th>Reserved function</th><th>Broad period</th></tr></thead><tbody><tr><td><a href='project-pilgrim.html'>XO-100 / O-100 Pilgrim</a></td><td>Crewed Mars transfer and atmospheric landing system</td><td>1981–1990 federal program</td></tr>${rows}</tbody></table></div><p>Except for Pilgrim, the entries record an incorporated requirement scheme rather than author-established programs.<sup class='canon-note' data-provenance='e'>[e]</sup></p>`};
  }
  deepSpaceCentury.related = deepSpaceCentury.related || [];
  for (const entry of deepSpaceRequirementLinks) {
    const item={href:`${entry.slug}.html`,kicker:`${entry.number} requirement`,label:entry.label};
    if (!deepSpaceCentury.related.some(existing => existing.href === item.href)) deepSpaceCentury.related.push(item);
  }
}
